2	/**
3	 * plan_checks.ts — one arm of `checks`, as a matrix.
4	 *
5	 * A workflow cannot read a file to decide its own jobs, so the list is published as a
6	 * job output and consumed with `fromJSON`. Each entry becomes one GitHub job, which is
7	 * what lets a job carry its own runner and — where the arm allows it — its own
8	 * secrets.
9	 *
10	 * ## Which configuration this reads
11	 *
12	 * Whichever tree the job that runs this checked out, and the two arms are deliberately
13	 * planned by two jobs for that reason.
14	 *
15	 * `from_pull_request` is planned from the PULL REQUEST's tree: they are its commands,
16	 * and it may change them freely, because no secret reaches them.
17	 *
18	 * `from_default_branch` is planned from the DEFAULT BRANCH's tree, and that is the
19	 * whole point of the arm. A pull request that could add a job, rename one, or widen
20	 * one's `secrets` would be a pull request choosing what it may reach.
21	 *
22	 * ## An empty list is an answer
23	 *
24	 * A project with no checks in an arm publishes `[]`, GitHub skips the matrix job, and
25	 * the job that aggregates the verdicts treats `skipped` as a pass. A malformed list is
26	 * NOT the same thing: it fails here, because a check that could not be planned must not
27	 * read as a check that found nothing to do.
28	 *
29	 * Usage:
30	 *   plan_checks.ts --arm pull-request|default-branch
31	 */
32	import { parseArgs } from "node:util";
33	import { CHECKS_FROM_DEFAULT_BRANCH, CHECKS_FROM_PULL_REQUEST, NO_PULL_REQUEST_CHECKS } from "../domain/check-jobs.ts";
34	import { getDefaultBranchChecks, getPullRequestChecks } from "../lib/config.ts";
35	import { publishMatrix } from "./lib/publish-matrix.ts";
36	import { defineScript } from "./lib/script-ref.ts";
37	
38	export interface PlanChecksArgs {
39	  arm: string;
40	}
41	
42	export const ref = defineScript<PlanChecksArgs>(import.meta.url);
43	
44	const ARMS = {
45	  "pull-request": { read: getPullRequestChecks, key: CHECKS_FROM_PULL_REQUEST.where, warnWhenEmpty: NO_PULL_REQUEST_CHECKS },
46	  "default-branch": { read: getDefaultBranchChecks, key: CHECKS_FROM_DEFAULT_BRANCH.where, warnWhenEmpty: "" },
47	} as const;
48	
49	export function main(): void {
50	  const { values } = parseArgs({ args: Bun.argv.slice(2), options: { arm: { type: "string" } } });
51	  const arm = ARMS[(values.arm ?? "") as keyof typeof ARMS];
52	  if (!arm) {
53	    console.error(`usage: plan_checks.ts --arm ${Object.keys(ARMS).join("|")}`);
54	    process.exit(2);
55	  }
56	
57	  const { jobs, problems } = arm.read();
58	  if (problems.length > 0) {
59	    for (const problem of problems) console.error(`::error::${problem}`);
60	    console.error(`::error::\`${arm.key}\` could not be read, so none of its checks ran.`);
61	    process.exit(1);
62	  }
63	
64	  publishMatrix(jobs, { what: `\`${arm.key}\` job`, warnWhenEmpty: arm.warnWhenEmpty });
65	}
